# enumerate shifts within same 9x13, matching output to AND with zero padding
for dy in range(-3,4):
 for dx in range(-4,5):
  sh=np.zeros_like(R)
  for y in range(9):
   for x in range(13):
    yy=y+dy;xx=x+dx
    if 0<=yy<9 and 0<=xx<13: sh[yy,xx]=R[y,x]
  mm=np.sum((L&sh)!=O)
  if mm<=12: print(dy,dx,mm,(L&sh).sum())
